'use strict';
(()=>{
 const $=id=>document.getElementById(id),dialog=$('buildDialog');let data,worker,generation=0;
 const types={'great-sword':'대검','long-sword':'태도','sword-shield':'한손검','dual-blades':'쌍검',hammer:'해머','hunting-horn':'수렵피리',lance:'랜스',gunlance:'건랜스','switch-axe':'슬래시액스','charge-blade':'차지액스','insect-glaive':'조충곤','light-bowgun':'라이트보우건','heavy-bowgun':'헤비보우건',bow:'활'};
 const parts={weapon:'무기',head:'머리',chest:'상의',arms:'팔',waist:'허리',legs:'다리',talisman:'호석'};
 function option(select,value,label){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o);}
 function stop(message){generation++;worker?.terminate();worker=null;$('buildStart').disabled=!data;$('buildCancel').disabled=true;if(message)$('buildStatus').textContent=message;}
 function invalidate(){if(!dialog.open)return;stop('조건이 변경되었습니다. 다시 검색하세요.');$('buildResults').replaceChildren();$('buildError').textContent='';}
 function weapons(){const s=$('buildWeapon');s.replaceChildren();for(const w of data.weapons.filter(w=>w.kind===$('buildType').value).sort((a,b)=>b.rarity-a.rarity||a.name.localeCompare(b.name,'ko')))option(s,w.id,`${w.name} · R${w.rarity} · 슬롯 ${w.slots.join('/')||'없음'}`);}
 function addGoal(){if($('buildGoals').children.length>=8)return;const row=document.createElement('div');row.className='build-goal';const label=document.createElement('label');label.textContent='목표 스킬';const select=document.createElement('select');select.className='build-skill';for(const s of [...data.skills].sort((a,b)=>a.name.localeCompare(b.name,'ko')))option(select,s.id,s.name+(['set','group'].includes(s.kind)?' · 세트/그룹':''));label.append(select);const levelsLabel=document.createElement('label');levelsLabel.textContent='목표 레벨 / 효과';const levels=document.createElement('select');levels.className='build-level';levelsLabel.append(levels);function update(){levels.replaceChildren();const s=data.skills.find(s=>s.id===Number(select.value));for(const r of s.ranks)option(levels,r.level,r.pieces?`${r.name} · ${r.pieces}부위`:`Lv.${r.level}`);}select.addEventListener('change',update);update();const remove=document.createElement('button');remove.type='button';remove.textContent='삭제';remove.addEventListener('click',()=>{row.remove();invalidate();});row.append(label,levelsLabel,remove);$('buildGoals').append(row);}
 function text(parent,tag,value){const el=document.createElement(tag);el.textContent=value;parent.append(el);return el;}
 function render(result){const container=$('buildResults');container.replaceChildren();result.results.forEach((r,i)=>{const card=document.createElement('article');card.className='build-card';text(card,'h3',`세팅 ${i+1} · 최대 강화 방어력 ${r.defense}`);text(card,'p',r.achieved.map(g=>`${g.name} Lv.${g.level}${g.pieces!==null?` (${g.pieces}부위)` : ''}`).join(' / '));const list=document.createElement('ul');for(const item of [r.weapon,...r.armor])text(list,'li',`${parts[item.part||'weapon']}: ${item.name} · 슬롯 ${item.slots.join('/')||'없음'}`);card.append(list);text(card,'p',r.charm?`호석: ${r.charm.skills.map(s=>`${s.name} Lv.${s.level}`).join(' / ')} · 무기 ${r.charm.weaponSlots.join('/')||'없음'} · 방어구 ${r.charm.armorSlots.join('/')||'없음'} · ${r.charmOwned?'보유':'규칙 후보'}`:'호석: 사용하지 않음');if(r.decorations.length){text(card,'h4','장식주 배치');const jewels=document.createElement('ul');for(const p of r.decorations)text(jewels,'li',`${parts[p.owner]} ${p.index+1}번 ${p.kind==='weapon'?'무기':'방어구'} 슬롯[${p.size}]: ${p.decoration.name}`);card.append(jewels);}else text(card,'p','장식주: 필요 없음');if(r.activeBonuses.length)text(card,'p','발동 효과: '+r.activeBonuses.map(b=>`${b.name} — ${b.effect} (${b.pieces}부위)`).join(' / '));container.append(card);});const limits={'result-limit':'대표 결과 20개 도달','time-limit':'20초 제한','node-limit':'탐색량 제한'};$('buildStatus').textContent=`${result.results.length}개 조합 · ${result.partial?`${limits[result.reason]||'제한'}으로 중단. 전체 탐색을 마치지 않았습니다.`:'지원 데이터 범위 검색 완료.'}${!result.results.length?' 조건을 낮추거나 호석 모드를 바꿔 보세요.':''}${result.excludedCharms?` 장비 데이터와 스킬이 맞지 않는 호석 후보 ${result.excludedCharms}건 제외.`:''}`;}
 $('buildNav').addEventListener('click',async()=>{dialog.showModal();if(data)return;$('buildStatus').textContent='장비 데이터를 불러오는 중…';try{const response=await fetch('data/equipment-snapshot.json');if(!response.ok)throw Error('장비 데이터 요청 실패');data=await response.json();$('buildSource').textContent=`MHDB 데이터 반영: ${data.apiImportVersion} · 게임 버전 미확인`;for(const [key,value]of Object.entries(types))option($('buildType'),key,value);$('buildType').value='long-sword';weapons();addGoal();$('buildStart').disabled=false;$('buildStatus').textContent='목표 스킬을 선택하고 검색하세요.';}catch(e){$('buildError').textContent=e.message;}});
 $('buildType').addEventListener('change',()=>{weapons();invalidate();});$('buildAddGoal').addEventListener('click',()=>{addGoal();invalidate();});$('buildForm').addEventListener('change',invalidate);
 $('buildClose').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{stop();$('buildNav').focus();});$('buildCancel').addEventListener('click',()=>stop('검색을 취소했습니다.'));document.addEventListener('inventory-state-changed',invalidate);
 $('buildForm').addEventListener('submit',event=>{event.preventDefault();stop();$('buildError').textContent='';$('buildResults').replaceChildren();const request={weaponId:Number($('buildWeapon').value),goals:[...$('buildGoals').children].map(row=>({id:Number(row.querySelector('.build-skill').value),level:Number(row.querySelector('.build-level').value)})),charmMode:$('buildMode').value,rank:$('buildRank').value,minDefense:Number($('buildDefense').value),records:window.CandidateContext.get().records};const token=generation;worker=new Worker('build-worker.js');$('buildStart').disabled=true;$('buildCancel').disabled=false;$('buildStatus').textContent='검색 준비 중…';worker.onmessage=({data:message})=>{if(token!==generation)return;if(message.type==='progress')$('buildStatus').textContent=message.phase==='charms'?`호석 후보 축소 중… ${message.examined||0}개 스킬 배정 확인`:`장비 탐색 중… ${message.nodes}회 / 결과 ${message.results}개`;else{stop();if(message.type==='error')$('buildError').textContent=message.message;else render(message);}};worker.onerror=()=>{stop();$('buildError').textContent='검색 작업을 실행하지 못했습니다. 새로고침 후 다시 시도하세요.';};worker.postMessage(request);});
})();
